B.a1w=new A.S(B.co,["qibli_mosque","Qibli Mosque","Main prayer hall with a silver dome.","The Qibli Mosque is the southern building within Al-Aqsa, serving as the main congregational prayer hall. It faces the Qibla and is known for its large prayer space and historical architecture.",B.X4,560,210,"Mosque"],t.yf)
B.Vw=A.a(s(["assets/images/al_marwani.jpg"]),t.s)
B.a1x=new A.S(B.co,["al_marwani","Al-Marwani Mosque","Underground mosque within Solomon's Stables.","Located in the southeastern corner of Al-Aqsa, Al-Marwani is an underground prayer hall built into a series of ancient vaults known as Solomon's Stables.",B.Vw,540,440,"Mosque"],t.yf)
B.ZB=A.a(s(["assets/images/dome_chain.jpg"]),t.s)
B.a1y=new A.S(B.co,["dome_chain","Dome of the Chain","Small dome next to Dome of the Rock.","The Dome of the Chain is a small open structure adjacent to the Dome of the Rock. Historically, it was a site of justice and preaching.",B.ZB,340,265,"Dome"],t.yf)
B.Yb=A.a(s(["assets/images/dome_ascension.jpg"]),t.s)
B.a1D=new A.S(B.co,["dome_ascension","Dome of the Ascension","Commemorates the Prophet\u2019s ascension.","This small dome marks the traditional location from which the Prophet Muhammad ascended during the Isra and Mi\u2019raj. It is a symbol of this spiritual event.",B.Yb,300,150,"Dome"],t.yf)
B.SE=A.a(s(["assets/images/dome_khalili.jpg"]),t.s)
B.a1z=new A.S(B.co,["dome_khalili","Dome of al-Khalili","Small domed structure named after a sheikh.","This dome is named after Sheikh Khalili and is one of the small structures used for prayer and retreat within the compound.",B.SE,175,145,"Dome"],t.yf)
B.Za=A.a(s(["assets/images/dome_prophet.jpg"]),t.s)
B.a1C=new A.S(B.co,["dome_prophet","Dome of the Prophet","Commemorates the Prophet\u2019s prayer spot.","This dome is believed to mark the spot where the Prophet Muhammad led the previous prophets in prayer before ascending to the heavens.",B.Za,310,170,"Dome"],t.yf)
B.SF=A.a(s(["assets/images/dome_spirits.jpg"]),t.s)
B.a1v=new A.S(B.co,["dome_spirits","Dome of the Spirits","One of the eastern domes.","This dome is one of the smaller domes located toward the eastern side of the Al-Aqsa compound, often used as a peaceful prayer space.",B.SF,130,210,"Dome"],t.yf)
B.SU=A.a(s(["assets/images/gate_tribes1.jpg","assets/images/gate_tribes2.jpg","assets/images/gate_tribes3.jpg"]),t.s)
B.a1A=new A.S(B.co,["gate_tribes","Gate of the Tribes (Bab al-Asbat)","Northern gate near the Dome of the Rock.","The Gate of the Tribes (Bab al-Asbat) is located at the northeastern corner of the Al-Aqsa Mosque compound and is historically used for access to residential areas around the site.",B.SU,100,480,"Gate"],t.yf)
